    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN are the same column, %r" % args[1])
    table = load(args[0])
    row_at, col_at, value_at = table.index(args[1]), table.index(args[2]), table.index(args[3])
    sums = {}
    heads = {}
    with localcontext(EXACT):
        for number, row in enumerate(table.rows, 1):
            head = row[col_at]
            if head == "":
                raise TabulaError("%s: row %d: column %r: empty value" % (table.source, number, args[2]))
            if head == args[1]:
                raise TabulaError("%s: row %d: column %r: value %r is the name of the row column"
                                  % (table.source, number, args[2], head))
            amount = _need_cell_number(table, number, args[3], row[value_at])
            heads[head] = None
            line = sums.setdefault(row[row_at], {})
            line[head] = line.get(head, 0) + amount
    rows = [[key] + [fmt_decimal(line[head]) if head in line else "0" for head in heads] for key, line in sums.items()]
    return Table([args[1]] + list(heads), rows, table.source)


